const entries=JSON.parse(readFileSync("release-packages.json","utf8")).filter(x=>candidateNames.has(x.name));
const remote=spawnSync("git",["ls-remote","--tags","origin"],{encoding:"utf8"}); if(remote.status!==0) throw new Error(remote.stderr);
const remoteTags=new Set(remote.stdout.trim().split(/\n/).filter(Boolean).map(line=>line.split(/\s+/)[1]?.replace("refs/tags/","").replace(/\^\{\}$/,"")));
const results=[]; const errors=[];
for(const e of entries){
 const latestRun=spawnSync("npm",["view",`${e.name}@latest`,"version","--json"],{encoding:"utf8"});
 if(latestRun.status!==0){errors.push(`${e.name}: latest lookup failed: ${latestRun.stderr.trim()}`); continue;}
 const latest=JSON.parse(latestRun.stdout); const m=String(latest).match(/^(\d+)\.(\d+)\.(\d+)$/);
 if(!m){errors.push(`${e.name}: non-stable latest ${latest}`); continue;}
 const proposed=`${m[1]}.${Number(m[2])+1}.0`; const tag=`${e.slug}-v${proposed}`;
 const exact=spawnSync("npm",["view",`${e.name}@${proposed}`,"version","--json"],{encoding:"utf8"});
 const combined=`${exact.stdout}\n${exact.stderr}`;
 const versionAbsent=exact.status!==0 && /E404|No match found|is not in this registry/i.test(combined);
 const localTag=spawnSync("git",["show-ref","--verify","--quiet",`refs/tags/${tag}`]).status===0;
 const remoteTag=remoteTags.has(tag);
 if(!versionAbsent) errors.push(`${e.name}@${proposed}: npm version is not conclusively absent`);
 if(localTag||remoteTag) errors.push(`${tag}: tag already exists (local=${localTag}, remote=${remoteTag})`);
 results.push({name:e.name,path:e.path,slug:e.slug,latest,proposed,distTag:"latest",tag,versionAbsent,localTagAbsent:!localTag,remoteTagAbsent:!remoteTag});
}
console.log(JSON.stringify({count:results.length,errors,results},null,2)); if(errors.length) process.exit(1);
